 test("MaxBars renderMaxWith runs a block operation with options.hash (ADR-019)", () => {
   const ops = { box: (xs, o) => safe('<ul class="' + o.hash.cls + '">' + xs.map((p) => o.fn(p)).join("") + "</ul>") };
